    h, w = len(grid), len(grid[0])
    if direction == 'cw':
        return [[grid[h-1-y][x] for y in range(h)] for x in range(w)]
    else:  # ccw
        return [[grid[y][w-1-x] for y in range(h)] for x in range(w)]

